    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/situations/0", "/situations/1"],
      "relevance": "내담자가 '어색한 말을 한다거나, 이 자리에 안 맞는 걸 꺼낸다거나 그러면 아, 이 사람 여기 사람이 아니구나 하는 게 확인될 것 같은 거요'라고 말한 부분은, 적극적으로 끼어들었다가 어울리지 못하면 외톨이임이 드러날 것이라는 부정적 가정과 직접 연결됨."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 '시도 안 하면 안 된 것도 아니니까, 그 모호함이 안전하긴 해요'라고 말한 부분은, 혼자 괜찮은 척하면 거절당하는 모습을 보이지 않고 체면을 지킬 수 있다는 긍정적 가정과 일치함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '다들 이미 편해 보여서, 내가 지금 들어가면 오히려 어색해질 것 같고요'라고 말한 부분은, 이미 서로 아는 사이에 뒤늦게 들어가는 것이 초라하고 어색하다는 태도와 연결됨. 어릴 때 네 번 전학하며 이미 친한 사이에 들어가야 했던 경험이 이 태도를 형성함."
    },
    {
      "trait_id": "/coping_strategies/0",
      "background_ids": ["/situations/0", "/situations/1"],
      "relevance": "내담자가 집에서는 끝나는 게 없는데도 '어차피'가 먼저 와서 빠질 이유를 만들어둔다고 말한 부분은, 초대받으면 핑계로 빠지는 회피 전략과 일치함. 상황 사례에서 동료가 저녁을 제안했을 때 약속이 있다고 둘러대거나, 독서 모임에 감기 기운으로 불참한 행동이 이 전략의 구체적 예시임."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/2"],
      "relevance": "내담자가 '원래 그 자리에 없던 사람'이라는 표현을 쓰며, 혼자 있는 건 지금 상태지만 없던 사람은 처음부터 거기가 아닌 것 같다고 구분한 부분은 사회적 고립/소외 도식과 직접 연결됨. 아들의 영상통화에서 '만나는 사람 없어?'라는 질문에 서운함과 체념을 느낀 것도 이 도식의 발현임."
    }
  ]
}

